// Love in Lagos frontend. Every screen talks to the backend through /api (see server/server.js).
const $=s=>document.querySelector(s),esc=s=>String(s==null?"":s).replace(/[&<>"]/g,k=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[k]));
let TOK="";try{TOK=localStorage.getItem("lil_token")||""}catch(e){}
const setTok=t=>{TOK=t;try{t?localStorage.setItem("lil_token",t):localStorage.removeItem("lil_token")}catch(e){}};
let me=null,BACK="",XPV=null,tab="home",sc=0,cur=null,T=0,UC={},PH={},M={incoming:[],matches:[],sent:[]},PEO=[],PREV=null,LOW={},DECL={},POPPED={},MINIT=0,MSG=[],GM=null,VIS=[],DLY=null,ACTV=[],QAL=[],SR=null,sT=0,after=null,phd="",tav=null,dr=null,dmode="";
async function api(m,p,b,ka){const r=await fetch("/api"+p,{method:m,keepalive:!!ka,headers:{"Content-Type":"application/json",...(TOK?{Authorization:"Bearer "+TOK}:{})},body:b===undefined?undefined:JSON.stringify(b)});let j=null;try{j=await r.json()}catch(e){}if(!r.ok){const e=new Error((j&&j.error)||"Something went wrong");e.status=r.status;if(r.status===401&&TOK&&me)setTimeout(()=>logout(true));throw e}return j}
const IC={h:"M12 21s-8-5.3-8-11a4.5 4.5 0 0 1 8-2.8A4.5 4.5 0 0 1 20 10c0 5.7-8 11-8 11z",u:"M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM4 21c0-4 3.6-7 8-7s8 3 8 7",c:"M21 12a8 8 0 0 1-11.5 7.2L4 20l1-4.6A8 8 0 1 1 21 12z",m:"M9 4 3 6v14l6-2 6 2 6-2V4l-6 2zM9 4v14M15 6v14",pin:"M12 21s7-6 7-11a7 7 0 0 0-14 0c0 5 7 11 7 11zM12 12a2 2 0 1 0 0-4 2 2 0 0 0 0 4z",sp:"M12 3l1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8z",ar:"M5 12h14M13 6l6 6-6 6",s:"M22 2 11 13M22 2l-7 20-4-9-9-4z",nav:"M3 11l19-9-9 19-2-8z",pp:"M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM2 21c0-4 3-6 7-6s7 2 7 6M16 3a4 4 0 0 1 0 8M18 15c2.5.6 4 2.4 4 6",eye:"M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12zM12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6z",x:"M6 6l12 12M18 6 6 18",pen:"M12 20h9M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4z"};
const ic=(d,f)=>`<svg class="ic" viewBox="0 0 24 24" fill="${f?"currentColor":"none"}" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="${d}"/></svg>`;
function toast(m){const e=document.createElement("div");e.className="toast";e.textContent=m;document.body.appendChild(e);setTimeout(()=>e.remove(),2600)}
const closeM=()=>{try{camStop()}catch(e){}try{StackGame.destroy()}catch(e){}clearTimeout(globalThis.__gameT);document.body.style.overflow="";document.querySelectorAll(".ov").forEach(e=>e.remove())};
function modal(h,c=""){closeM();const o=document.createElement("div");o.className="ov "+c;o.innerHTML=`<div class="md ${c}">${h}</div>`;o.onclick=e=>{if(e.target===o)closeM()};document.body.appendChild(o)}
const gate=w=>`<div class="card gt">${ic(IC.h)}<h2>Sign in to ${w}</h2><p class="sub">Create a free account to play and chat.</p><button class="btn" onclick="openAuth('up')">Create account</button><button class="btn o" onclick="openAuth('in')">Log in</button></div>`;
// ---------- people, bitmojis ----------
const avOf=u=>({sk:"#a8714f",sh:"#dc5f84",bg:"#f6e3f8",...(u.avatar||{})});
const av=(u,s)=>AV(avOf(u),s);
const face=(u,s)=>PH[u.id]?`<img class="av" width="${s}" height="${s}" src="${PH[u.id]}" style="object-fit:cover">`:av(u,s);
const st=()=>{const g=me.game=me.game||{};return g.st=g.st||{en:100,mo:70,t:Date.now()}};
function regen(){const s=st(),n=Math.floor((Date.now()-s.t)/3e4);if(n>0){s.en=Math.min(100,s.en+n);s.t+=n*3e4}}
const saveGame=()=>api("PUT","/me",{game:me.game}).catch(()=>{});
// ---------- navigation + render ----------
function nav(t){if(tab==="me")psFlush();tab=t;cur=null;MR=0;BACK="";POLL.act=Date.now();pollNow("mat","ppl","vis","not");render();if(t==="daily")loadDaily();if(t==="corner")loadVisitors();if(t==="chat")loadMatches();if(t==="me")loadXP()}
function go(i){sc=i;PEO=[];PREV=null;presence();render(1);loadPeople()}
function pick(i){if(tab!=="home")BACK=tab;sc=i;tab="home";cur=null;PEO=[];PREV=null;presence();render();loadPeople();toast("Heading to "+SCN[i][1])}
const navHTML=()=>[["corner","Corner","🏠"],["daily","Daily","🗓️"],["chat","Chat",IC.c],["map","Map",IC.m]].map(x=>`<button class="${tab===x[0]?"on":""}" onclick="nav('${x[0]}')">${x[2].length<4?`<span class="ne">${x[2]}</span>`:ic(x[2])}${x[1]}${x[0]==="chat"&&M.incoming.length?`<i class="bdg">${M.incoming.length}</i>`:""}</button>`).join("");
function render(keep){const m=$("main"),s0=keep&&m?m.scrollTop:0,body=tab==="home"?home():tab==="map"?mapV():tab==="chat"?chatV():tab==="corner"?cornerV():tab==="daily"?dailyV():prof();
$("#app").innerHTML=`<header><div class="lg" onclick="nav('home')"><i>${ic(IC.pin,1)}</i>Love in Lagos</div><button class="hb" onclick="nav('chat')" aria-label="Chats">${ic(IC.c)}</button><button class="hb" onclick="openNotifs()" aria-label="Notifications"><span style="font-size:20px">🔔</span><i class="bd" id="nbd"></i></button><button class="pf" onclick="nav('me')">${me?av(me,26):ic(IC.u)}${me?esc(me.name):"Sign in"}</button></header><main>${body}</main><nav>${navHTML()}</nav>`;
if(keep&&$("main"))$("main").scrollTop=s0;if(tab==="home"&&sc===0)road();if(tab==="home"&&sc===8)live();if(tab==="home"&&sc!==8)liveCap();if(tab==="chat"&&cur)drawThread();saveView();charmPill();nBadge()}
// ---------- home: location, activities, people around you ----------
function stats(){if(!me)return `<div class="bd">${ic(IC.sp)} Sign in to start your life in Lagos</div>`;regen();const s=st(),b=(e,n,v,k)=>`<div class="sb">${e} ${n}<i><u style="width:${v}%;background:${k}"></u></i></div>`;return `<div class="stats">${b("⚡","Energy",s.en,"#f4b942")}${b("😊","Mood",s.mo,"#dc5f84")}</div>`}
const aroundHTML=()=>!me?'<p class="sub">Sign in to see who is around you.</p>':PEO.length?`<div class="grid">${PEO.map(p=>`<button class="pc" onclick="bio(${p.id})">${av(p,62)}<h3>${esc(p.name)}</h3><div class="jb">${esc(p.area||"Lagos")}</div><div class="gk">Meet ${esc(p.name)} ${ic(IC.ar)}</div></button>`).join("")}</div>`:'<p class="sub">No one else is here right now. Try another spot!</p>';
const pplHTML=()=>sc===8||!me?"":PEO.slice(0,4).map((p,i)=>`<button class="pp" style="left:${POS[i][0]}%;top:${POS[i][1]}%" onclick="bio(${p.id})"><span class="hv">👋</span>${av(p,66)}<span class="nm">${esc(p.name)}</span></button>`).join("");
function refreshPeople(){const a=$("#ppl"),b=$("#pcg");if(a)a.innerHTML=pplHTML();if(b)b.innerHTML=aroundHTML()}
function arrive(p){const e=document.createElement("button");e.className="arr";e.innerHTML=`${av(p,40)}<span><b>${esc(p.name)}</b> just arrived at ${SCN[sc][0]} 👋<small>Tap to say hi</small></span>`;e.onclick=()=>{e.remove();bio(p.id)};document.body.appendChild(e);setTimeout(()=>e.remove(),5000)}
async function loadPeople(){if(!me)return;const l=sc;let r;try{r=await api("GET","/people?loc="+l)}catch(e){return}if(l!==sc)return;r.forEach(u=>UC[u.id]=u);const ids=r.map(u=>u.id),nw=PREV&&ids.find(i=>!PREV.includes(i));PREV=ids;PEO=r;if(tab==="home"){refreshPeople();if(nw)arrive(UC[nw])}}
const presence=()=>{if(me)api("POST","/presence",{loc:sc}).catch(()=>{})};
function home(){return `${backBtn()}<h1>Your Lagos. Your day.</h1><p class="sub">Hang out, explore and make friends across the city.</p>${stats()}${charmBar()}<div class="tabs">${SCN.map((s,i)=>`<button class="${i===sc?"on":""}" onclick="go(${i})">${EM[i]} ${s[0]}</button>`).join("")}</div>
<div class="scn">${scene(sc)}${sc===0?'<div class="road"></div>':""}<div class="live">${sc===8?parkHTML():liveHTML(sc)}</div><div class="ttl"><b>${ic(IC.pin)}${SCN[sc][1]} <em class="lvb">● LIVE</em></b><small${sc===8?"":' id="lvc"'}>${sc===8?'⚽ Red <i id="sa">0</i> – <i id="sb">0</i> Blue · 🏀 · 🎾':LCAP[sc][0]}</small></div><div id="ppl" class="ppl">${pplHTML()}</div></div>
<h2 class="sec">Things to do here</h2><div class="acts">${ACT[sc].map((a,i)=>`<button class="ac" onclick="act(${i})"><span class="e">${a[1]}</span><b>${a[0]}</b><small>⚡${a[2]>0?"+":""}${a[2]} · 😊${a[3]>0?"+":""}${a[3]}</small></button>`).join("")}</div><button class="btn o" onclick="rest()">🛏️ Rest at home (+40 ⚡)</button>
<div class="tip"><i>${ic(IC.sp)}</i><div><b>Every spot has something to do.</b><span>Try everything and meet new friends across Lagos.</span></div></div>
<section class="card"><div class="ch"><h2 style="color:var(--ink)">People around you</h2>${ic(IC.pp)}</div><div id="pcg">${aroundHTML()}</div></section>
<footer><span>Made for the way Lagos connects.</span><span>Take it slow. Keep it kind.</span></footer>`}
function act(i){if(!me)return openAuth("up");regen();const a=ACT[sc][i],s=st();if(s.en+a[2]<0)return toast("Too tired. Rest first 😮‍💨");s.en=Math.min(100,s.en+a[2]);s.mo=Math.max(0,Math.min(100,s.mo+a[3]));const m=a[4].split("|");api("POST","/activity",{kind:"act",text:a[1]+" "+a[0]+" at "+SCN[sc][0]}).then(loadXP).catch(()=>{});saveGame();toast(a[1]+" "+m[Math.floor(Math.random()*m.length)]);render(1)}
function rest(){if(!me)return openAuth("up");regen();const s=st();s.en=Math.min(100,s.en+40);s.mo=Math.min(100,s.mo+5);api("POST","/activity",{kind:"rest",text:"🛏️ Rested at home"}).catch(()=>{});saveGame();toast("🛏️ You napped. Feeling fresh!");render(1)}
// ---------- profile popup + matching ----------
const IL=["music","food","travel","art","tech","books","dance","fitness","football","movies","poetry","coffee","beach","fashion","games","nightlife","jollof","suya","photography","business"];
const AREAS=["Lekki","Victoria Island","Ikoyi","Yaba","Surulere","Ikeja","Ajah","Festac","Maryland","Gbagada","Lagos Island","Badagry"],LOOK=["New friends","Dating","Just vibes","Activity partners"];
function relOf(id){if(M.matches.some(x=>x.user.id===id))return"chat";if(M.sent.some(x=>x.user.id===id))return"sent";if(LOW[id]!==undefined)return"low";if(DECL[id])return"no";return""}
function bio(id){const p=UC[id];if(!p)return;const self=me&&me.id===id,st=me&&!self?relOf(id):"",inc=me&&M.incoming.find(x=>x.user.id===id);if(me&&!self)api("POST","/profile-views",{userId:id}).catch(()=>{});
const b=!me?`<button class="btn" onclick="openAuth('up',${id})">Sign in to match</button><p class="note">You need an account to match with people.</p>`:self?'<p class="note">This is your profile.</p>':st==="chat"?`<button class="btn" onclick="openChat(${id})">Open chat</button><button class="btn" onclick="invite(${id})">🎲 Play 20 Questions</button>`:inc?`<button class="btn" onclick="incA(${inc.requestId},${id},1)">💘 Match back (${inc.pct}%)</button>`:st==="sent"?'<button class="btn dis" disabled>Match sent · waiting…</button>':st==="low"?'<button class="btn dis" disabled>Low match · not sent</button>':st==="no"?'<button class="btn dis" disabled>Not a match this time</button>':`<button class="btn" onclick="doMatch(${id})">💘 ${charmOn()?"Match instantly ⚡":"Match"}</button>`;
modal(`<div class="bc">${face(p,92)}<h2>${esc(p.name)} ${(f=>lvt(f)+tgs(f))((M.matches||[]).find(x=>x.user.id===p.id))}</h2><div class="jb">@${esc(p.username)}${p.area?" · "+esc(p.area):""}</div><div class="loc">${ic(IC.pin)}${p.online&&SCN[p.loc]?"Online now · "+SCN[p.loc][0]:"Offline right now"}</div><p class="bt">${esc(p.bio||"No about yet.")}</p>${p.fav?`<div class="jb">Favourite spot: ${esc(p.fav)}</div>`:""}<div class="tags">${(p.interests||[]).map(t=>`<span>${esc(t)}</span>`).join("")}</div>${me&&!self&&(p.interests||[]).some(t=>(me.interests||[]).includes(t))?`<p class="note">In common with you: ${(p.interests||[]).filter(t=>(me.interests||[]).includes(t)).map(esc).join(", ")}</p>`:""}${me&&!self?`<div class="gift"><span>🎁 Gift XP</span>${[10,25,50,100,500,1000].map(n=>`<button onclick="giftXP(${p.id},${n})">${n}</button>`).join("")}</div>`:""}${me&&!self?`<div class="gift"><button onclick="closeM();openCupid(${p.id})">💘 Match them with someone</button></div>`:""}</div>${me&&!self&&!st&&!inc?`<p class="note" style="margin-bottom:6px">Would you like to match with ${esc(p.name)}?</p>`:""}${b}<button class="btn o" onclick="closeM()">Not now</button>${me&&!self?`<p class="note"><a class="lnk2" onclick="reportU(${id})">Report</a> · <a class="lnk2" onclick="blockU(${id})">Block</a></p>`:""}`)}
async function blockU(id){if(!confirm("Block this person? You won't see each other again."))return;try{await api("POST","/block",{userId:id});closeM();toast("Blocked");loadMatches();loadPeople()}catch(e){toast(e.message)}}
async function reportU(id){const r=prompt("What happened? (a few words)");if(!r)return;try{await api("POST","/report",{userId:id,reason:r});closeM();toast("Thanks, we'll look into it")}catch(e){toast(e.message)}}
// the % counts up on screen, then the result and buttons appear
function countTo(p,pc,fin){modal(`<div class="bc">${face(p,80)}<div class="pcn" id="pcn">0%</div><h2 id="pct">Checking your match…</h2><p class="bt" id="pcm"></p></div><div id="pcb"></div>`);let n=0;const stp=Math.max(1,Math.round(pc/40)),iv=setInterval(()=>{const e=$("#pcn");if(!e)return clearInterval(iv);n=Math.min(pc,n+stp);e.textContent=n+"%";if(n>=pc){clearInterval(iv);fin(h=>{$("#pct").innerHTML=h[0];$("#pcm").innerHTML=h[1];$("#pcb").innerHTML=h[2]})}},45)}
const okb='<button class="btn" onclick="closeM()">OK</button>';
// <=20% not sent | 21-50% worth a trial | 51-79% potential | 80-94% interesting | 95%+ instant match (the server decides which)
async function doMatch(id){if(!me)return openAuth("up",id);const p=UC[id];let r;try{r=await api("POST","/matches",{to:id})}catch(e){return toast(e.message)}const ch=charmOn()&&r.status==="matched",pc=ch?100:r.pct,nm=esc(p.name),wy=(r.boost?" ⚡ Lagos Charm made it instant.":"")+(r.why&&r.why.length?" You two share: "+r.why.map(esc).join(", ")+".":" No checklist needed: chemistry does not always follow the rules.");
if(r.status==="low"){LOW[id]=pc;return countTo(p,pc,f=>f(["💔 Not a match","Not enough in common. We didn't send your result to "+nm+"."+wy,okb]))}
if(r.status==="declined"){DECL[id]=1;return countTo(p,pc,f=>f(["🙁 Not this time",nm+" isn't ready to match right now.",okb]))}
if(r.status==="matched"){POPPED[id]=1;loadMatches();return countTo(p,pc,f=>f([ch?"⚡ Charm match! 💘":"It's a match! 💘","No waiting needed. Do you want to ask where "+nm+" has been all your life?"+wy+" You both automatically got the "+lvl(r.pct)+" and 💬 Talking stage tags.",`<button class="btn" onclick="askWhere(${id})">Ask ${nm} 😍</button><button class="btn o" onclick="closeM();setTimeout(()=>matchPop(${id}),300)">Not yet</button>`]))}
loadMatches();const t=pc<=50?["🙂 Might be worth a trial","Not a perfect score, but chemistry can surprise you. Your result was sent to "+nm+"."+wy+" If they accept, you both get the "+lvl(r.pct)+" tag."]:pc<80?["✨ Now we're talking!","You two have real potential. Your result was sent to "+nm+"."+wy+" If they accept, you both get the "+lvl(r.pct)+" tag."]:["🔥 Ooh, this is interesting!","The sparks are real. Your result was sent to "+nm+"."+wy+" If they accept, you both get the "+lvl(r.pct)+" tag."];countTo(p,pc,f=>f([t[0],t[1],okb]))}
async function askWhere(id){closeM();try{await api("POST","/messages/"+id,{text:"Where have you been all my life? 😍"})}catch(e){toast(e.message)}openChat(id)}
function matchPop(id){const p=UC[id];if(!p)return;modal(`<div class="bc">${face(p,92)}<h2>It's a match! 🎉</h2><p class="bt">You and ${esc(p.name)} are connected.${(f=>f?" You both got the "+lvl(f.pct)+" tag"+(f.talking?" and 💬 Talking stage":"")+".":"")(M.matches.find(x=>x.user.id===id))} Want to play <b>20 Questions</b>? ${esc(p.name)} gets to choose yes or no.</p></div><button class="btn" onclick="invite(${id})">🎲 Invite ${esc(p.name)} to play</button><button class="btn o" onclick="closeM()">Maybe later</button>`)}
async function incA(rid,id,y){closeM();try{await api("POST","/matches/"+rid+"/respond",{accept:!!y})}catch(e){return toast(e.message)}await loadMatches();if(y){POPPED[id]=1;toast("It's a match with "+UC[id].name+" 🎉");matchPop(id)}}
async function loadMatches(){if(!me&&!TOK)return;let r;try{r=await api("GET","/matches")}catch(e){return}
const hadI=M.incoming.map(x=>x.requestId),hadM=M.matches.map(x=>x.user.id),hadS=M.sent.map(x=>x.user.id);M=r;[...r.incoming,...r.matches,...r.sent].forEach(x=>UC[x.user.id]=x.user);const ids=r.matches.map(x=>x.user.id);
if(MINIT){const ni=r.incoming.find(x=>!hadI.includes(x.requestId));if(ni)toast("💌 New match request from "+ni.user.name);
hadS.filter(i=>!ids.includes(i)&&!r.sent.some(x=>x.user.id===i)).forEach(i=>{DECL[i]=1;toast(UC[i].name+" isn't ready to match right now")});
ids.filter(i=>!hadM.includes(i)&&!POPPED[i]).forEach(i=>{POPPED[i]=1;toast(UC[i].name+" matched with you 🎉");setTimeout(()=>matchPop(i),600)})}
MINIT=1;r.matches.forEach(x=>{if(x.photoUnlocked&&PH[x.user.id]===undefined)loadPhoto(x.user.id)});
if($("nav"))$("nav").innerHTML=navHTML();if(tab==="chat"&&!cur&&$("#cl")){if(MR)$("#cl").innerHTML=mrList();else if($("#cs")&&!$("#cs").value)$("#cl").innerHTML=chList("")}}
async function loadPhoto(id){PH[id]=null;try{const r=await api("GET","/photo/"+id);if(r.photo){PH[id]=r.photo;if(tab==="chat"){const v=$("#ci")&&$("#ci").value,g=$("#gi")&&$("#gi").value;render(1);if(v&&$("#ci"))$("#ci").value=v;if(g&&$("#gi"))$("#gi").value=g}}else setTimeout(()=>{if(PH[id]===null)delete PH[id]},3e5)}catch(e){setTimeout(()=>{if(PH[id]===null)delete PH[id]},15e3)}} // no picture yet: look again in 5 minutes; a failed try: again in 15 seconds
// ---------- chats ----------
const lvl=p=>p>=91?"💖 Perfect Match":p>=80?"🔥 Sparks Flying":p>=51?"✨ Real Potential":"🌱 Worth a Trial",lvc=p=>p>=91?4:p>=80?3:p>=51?2:1,lvt=m=>m?`<span class="tag lv${lvc(m.pct)}">${lvl(m.pct)}</span>`:"";
const tgs=m=>m&&m.talking?'<span class="tag">💬 Talking stage</span>':"";
const rowU=(u,sub,extra)=>`<button class="row" onclick="${extra}">${face(u,48)}<div><b>${esc(u.name)}</b>${sub}</div></button>`;
let MR=0,CT="msg";
const GK=()=>"lil_gs_"+(me?me.id:0)+"_"+cur,gsig=()=>!GM||GM.status==="declined"?"none":JSON.stringify([GM.id,GM.status,GM.i,GM.cur?[GM.cur.q!=null,GM.cur.yourTurnToAsk,GM.cur.yourTurnToAnswer]:0]);
const mrCard=x=>`<div class="row"><span onclick="bio(${x.user.id})" style="cursor:pointer">${av(x.user,48)}</span><div onclick="bio(${x.user.id})" style="cursor:pointer"><b>${esc(x.user.name)}</b><div class="jb">${x.pct}% match</div></div><button class="mb y" onclick="incA(${x.requestId},${x.user.id},1)">Match</button><button class="mb" onclick="incA(${x.requestId},${x.user.id},0)">Not now</button></div>`;
const mrList=()=>M.incoming.length?M.incoming.map(mrCard).join(""):'<p class="note" style="text-align:left">No match requests right now.</p>';
function mrToggle(v){MR=v;render();if(v)loadMatches()}
function chList(q){if(q){return SR===null?'<p class="sub">Searching…</p>':SR.length?SR.map(u=>rowU(u,`<div class="jb">@${esc(u.username)}${u.area?" · "+esc(u.area):""}</div>`,`bio(${u.id})`)).join(""):'<p class="sub">No one found with that username.</p>'}
const ms=M.matches.slice().sort((a,b)=>((b.last&&b.last.created)||0)-((a.last&&a.last.created)||0)),n=M.incoming.length;
return `<button class="mrh" onclick="mrToggle(1)" aria-label="Open match requests"><span><b>Match Requests</b><small>${n?n+" waiting":"No new requests"}</small></span>${n?`<i class="mrn">${n}</i>`:""}<em>›</em></button><h3 class="sec">Recent Chats</h3>`+(ms.length||M.sent.length?"":'<p class="sub">No chats yet. Tap someone on the street and match.</p>')+ms.map(x=>`<button class="row" onclick="openChat(${x.user.id})">${face(x.user,48)}<div><small class="rn">${esc(x.user.name)}</small><div class="ru"><b>@${esc(x.user.username)}</b>${lvt(x)}${tgs(x)}</div><div class="jb">${x.last?esc(x.last.text):"Say hi 👋"}</div></div></button>`).join("")+M.sent.map(x=>`<div class="row"><span onclick="bio(${x.user.id})" style="cursor:pointer">${av(x.user,48)}</span><div><b>${esc(x.user.name)}</b><div class="jb">Match sent · waiting…</div></div></div>`).join("")}
function chSearch(v){v=v.trim().toLowerCase();clearTimeout(sT);if(!v){SR=null;$("#cl").innerHTML=chList("");return}SR=null;$("#cl").innerHTML=chList(v);sT=setTimeout(async()=>{try{SR=await api("GET","/people?q="+encodeURIComponent(v))}catch(e){SR=[]}SR.forEach(u=>UC[u.id]=u);if($("#cs")&&$("#cs").value.trim().toLowerCase()===v)$("#cl").innerHTML=chList(v)},250)}
function chatV(){if(!me)return gate("chat");if(cur)return thread();if(MR)return `<button class="bk" onclick="mrToggle(0)"><span>← Return to Chats</span></button><h2>Match Requests</h2><div id="cl">${mrList()}</div>`;return `<h2>Chats</h2><input id="cs" class="srch" placeholder="🔍 Search people by username" oninput="chSearch(this.value)"><div id="cl">${chList("")}</div>`}
function thread(){const u=UC[cur],mt=M.matches.find(x=>x.user.id===cur)||{};return `<div class="thx"><div class="th"><button class="hb" onclick="cur=null;render();loadMatches()" aria-label="Back to chats">${ic(IC.ar)}</button><span onclick="bio(${cur})" style="cursor:pointer">${face(u,44)}</span><div style="flex:1"><b>${esc(u.name)}</b>${tagB(mt)}<div class="jb">@${esc(u.username)}</div></div></div><div class="ctabs"><button id="tm" class="${CT==="msg"?"on":""}" onclick="ctab('msg')">💬 Messages</button><button id="tg" class="${CT==="game"?"on":""}" onclick="ctab('game')">🎮 20 Questions<i id="gbd" class="gbd hid"></i></button></div></div><div id="pm" class="${CT==="msg"?"":"hid"}"><div id="gind"></div><div id="msgs"></div><div class="cin"><div id="rbar" class="rbar hid"></div><input id="ci" placeholder="Say something kind…" onkeydown="if(event.key==='Enter')send();else if(event.key==='Escape')clearReply()"><button class="btn" onclick="send()" aria-label="Send message">${ic(IC.s)}</button></div></div><div id="pg" class="${CT==="game"?"":"hid"}"><div id="gp"></div><div id="gcin" class="cin hid"><input id="gi" placeholder="Type your answer to the question…" onkeydown="if(event.key==='Enter')gAnswer()"><button class="btn" onclick="gAnswer()" aria-label="Send answer">${ic(IC.s)}</button></div></div>`}
async function openChat(id,t){closeM();RPL=null;tab="chat";cur=id;CT=t||"msg";MR=0;MSG=[];GM=null;render();await loadThread()}
async function loadThread(auto){if(!cur||!me)return;if(!auto)POLL.hot=Date.now()+6e4;const id=cur;let ms,g;const needG=!auto||(GM&&(GM.status==="playing"||GM.status==="invited"))||due("gm",15000); // with no game running, the game state is only checked every 15 s
try{[ms,g]=await Promise.all([api("GET","/messages/"+id+"?after="+(MSG.length?MSG[MSG.length-1].id:0)),needG?api("GET","/games/with/"+id):Promise.resolve(GM)])}catch(e){if(e.status===403){toast("You can only chat with your matches");cur=null;render()}return}
if(id!==cur)return;const changed=ms.length||JSON.stringify(g)!==JSON.stringify(GM),first=!MSG.length;MSG=MSG.concat(ms);GM=g;{const mt=M.matches.find(x=>x.user.id===id);if(mt&&!first&&ms.length){mt.count=(mt.count||0)+ms.length;if(mt.count>=100&&!mt.photoUnlocked)await loadMatches()}}if(changed){POLL.hot=Date.now()+6e4;drawThread()}}
function ctab(t){CT=t;[["#tm","msg"],["#tg","game"]].forEach(([k,v])=>{const b=$(k);if(b)b.classList.toggle("on",v===t)});if($("#pm"))$("#pm").classList.toggle("hid",t!=="msg");if($("#pg"))$("#pg").classList.toggle("hid",t!=="game");gBadge();if($("main"))$("main").scrollTop=1e9}
function gBadge(){const b=$("#gbd");if(!b||!cur)return;const s=gsig();try{if(CT==="game"||s==="none"){if(s!=="none")localStorage.setItem(GK(),s);b.classList.add("hid");return}b.classList.toggle("hid",localStorage.getItem(GK())===s)}catch(e){b.classList.add("hid")}}
function gInd(){if(!GM||GM.status==="declined")return"";const u=UC[cur];let t;if(GM.status==="invited")t=GM.inviter===me.id?"waiting for "+esc(u.name):"invite waiting for you";else if(GM.status==="done")t="completed 🎉";else t=Math.min(20,GM.i)+"/20"+(GM.cur&&(GM.cur.yourTurnToAsk||GM.cur.yourTurnToAnswer)?" · your turn":"");return `<button class="gind" onclick="ctab('game')">🎮 <b>20 Questions</b> · ${t}</button>`}
function drawThread(){const e=$("#msgs"),g=$("#gp");if(!e||!g||!cur)return;if(SW.on){SW.redraw=true;return}const mu=M.matches.find(x=>x.user.id===cur)&&M.matches.find(x=>x.user.id===cur).photoUnlocked;e.innerHTML=MSG.map((x,i)=>`<div class="m ${x.from_id===me.id?"me":""}" data-id="${x.id}">${quoteHTML(x)}${esc(x.text)}<small>${new Date(x.created).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"})}</small></div>`+(i===99&&mu?`<div class="sysmsg" role="status">📸 You can now see each other's profile pictures!</div>`:"")).join("");$("#gind").innerHTML=gInd();g.innerHTML=gpHTML(UC[cur]);const c=GM&&GM.status==="playing"&&GM.cur&&GM.cur.yourTurnToAnswer;$("#gcin").classList.toggle("hid",!c);gBadge();renderReplyBar();if($("main"))$("main").scrollTop=1e9}
// the 20 Questions game has its own tab. It never shares an input or an API call with ordinary messages.
const gpHTML=u=>{const n=esc(u.name),inv=l=>`<button class="btn" onclick="invite(${u.id})">${l}</button>`;
if(!GM||GM.status==="declined")return `<div class="gq iv"><b>🎲 20 Questions</b><span>Play with ${n}. The game has its own space, so your chat stays separate.</span>${inv("Invite "+n+" to play")}</div>`;
const hist=(GM.history||[]).map(h=>`<div class="gq"><small>${h.asker===me.id?"You asked":n+" asked"}</small>${esc(QB[h.q]?QB[h.q][1]:"")}<div class="ans">${esc(h.answer||"")}</div></div>`).join("");
if(GM.status==="invited")return GM.inviter===me.id?`<div class="gq iv"><b>🎲 20 Questions</b><span>Waiting for ${n} to say yes or no…</span></div>`:`<div class="gq iv"><b>🎲 20 Questions</b><span>${n} wants to play. Are you in?</span><div class="two"><button class="btn" onclick="gResp(1)">Yes, let's play</button><button class="btn o" onclick="gResp(0)">No thanks</button></div></div>`;
if(GM.status==="done")return hist+'<div class="gq">🎉 That\'s all 20! You two know each other so much better now.</div>'+inv("Play again 🎲");
const c=GM.cur||{},q=c.q!=null&&QB[c.q]?QB[c.q]:null,hd=`Question ${GM.i+1} of 20${q?" · "+CAT[q[0]]:""}`,pr=`<div class="gpr" aria-label="Question ${GM.i+1} of 20"><i style="width:${Math.round(GM.i/20*100)}%"></i></div>`;
return pr+hist+(c.yourTurnToAsk&&q?`<div class="gq"><small>${hd} · your turn to ask</small>${esc(q[1])}<div class="gqa"><button class="btn" onclick="askIt()">Ask it 👉</button><button class="btn gsw" onclick="swapQ()" aria-label="Change question" title="Change question">↻</button></div></div>`:c.yourTurnToAnswer&&q?`<div class="gq"><small>${hd} · ${n} asks</small>${esc(q[1])}<small>Type your answer in the box below</small></div>`:`<div class="gq"><small>${hd}</small>${c.asker===me.id?`Waiting for ${n} to answer…`:`${n} is picking a question…`}</div>`)};
async function invite(id){if(!me)return openAuth("up");closeM();try{await api("POST","/games/invite",{userId:id})}catch(e){if(e.status!==409)return toast(e.message)}openChat(id,"game")}
async function gResp(y){try{await api("POST","/games/"+GM.id+"/respond",{accept:!!y})}catch(e){toast(e.message)}loadThread()}
async function swapQ(){if(swapQ.b||!GM)return;swapQ.b=1;try{await api("POST","/games/"+GM.id+"/swap",{})}catch(e){toast(e.status===404?"Changing questions needs the latest server update":e.message)}swapQ.b=0;loadThread()}
async function askIt(){try{await api("POST","/games/"+GM.id+"/ask",{})}catch(e){toast(e.message)}loadThread()}
async function send(){const i=$("#ci"),t=i.value.trim();if(!t)return;i.value="";try{const body={text:t};if(RPL)body.replyTo=RPL.id;const r=await api("POST","/messages/"+cur,body);clearReply();if(r&&r.photosUnlocked)await loadMatches()}catch(e){toast(e.message);i.value=t;return}await loadThread()}
async function gAnswer(){const i=$("#gi"),t=i.value.trim();if(!t||!GM||GM.status!=="playing")return;i.value="";try{await api("POST","/games/"+GM.id+"/answer",{text:t})}catch(e){toast(e.message);i.value=t;return}await loadThread()}
