modal(`<div class="stack-game-head"><div><b>Stack Game</b><small>Tap, click or press Space to drop each slab.</small></div><a class="stack-game-new" href="${GAME_URL}" target="_blank" rel="noopener" aria-label="Open the game in a new tab">↗</a><button class="stack-game-close" type="button" onclick="closeM()" aria-label="Close game">✕</button></div><div class="stack-game-box"><div class="stack-game-load" id="sgl"><span class="sgs"></span><p>Loading the game…</p></div><iframe id="sgf" class="stack-game-frame" src="${GAME_URL}" title="Love in Lagos Stack Game" allow="autoplay; fullscreen; gyroscope; accelerometer"></iframe></div><p class="stack-game-foot">Your game best is saved on this device. <a href="${GAME_URL}" target="_blank" rel="noopener">Not working? Open it in a new tab</a></p>`,"stack-game-overlay");document.body.style.overflow="hidden";
