let CP=null;
async function loadCupid(){if(!me)return;try{CP=await api("GET","/cupid");[...CP.mine.flatMap(c=>[c.a,c.b]),...CP.top.map(x=>x.user)].forEach(u=>{if(u)UC[u.id]=u});if(tab==="daily")render(1)}catch(e){}}
const cupidCard=()=>{if(!CP)return"";const ch={open:"waiting…",matched:"matched! 🎉"};return `<div class="card cpd"><b>💘 Aunty Matchmaker</b><p class="sub" style="margin:2px 0 10px">Think two people would click? Introduce them. You earn <b>+60 XP</b> if they match. You can introduce ${CP.left} more today.</p><button class="btn" onclick="openCupid()">Play Cupid 💘</button>${CP.matched?`<p class="note">Couples you matched: <b>${CP.matched}</b></p>`:""}${CP.mine.map(c=>`<div class="row" style="padding:6px 0">${av(c.a,32)}<span>+</span>${av(c.b,32)}<div style="flex:1;font-size:14px">${esc(c.a.name)} &amp; ${esc(c.b.name)}</div><span class="jb">${ch[c.status]||c.status}</span></div>`).join("")}${CP.top.length?`<p class="note" style="text-align:left;margin-top:10px"><b>Top matchmakers:</b> ${CP.top.map((x,i)=>(i+1)+". "+esc(x.user.name)+" ("+x.count+")").join(" · ")}</p>`:""}</div>`};
function openCupid(pre){const us=Object.values(UC).filter(u=>u&&u.id!==me.id).sort((x,y)=>String(x.name).localeCompare(String(y.name)));if(us.length<2)return toast("Visit a spot and meet a few people first");const d1=pre||us[0].id,d2=us.find(u=>u.id!==d1).id,o=s=>us.map(u=>`<option value="${u.id}" ${u.id===s?"selected":""}>${esc(u.name)}</option>`).join("");
modal(`${xb()}<h2 class="at">💘 Aunty Matchmaker</h2><p class="sub as">Pick two people you think would click. We tell both of them. If they match, you earn 60 XP.</p><label>First person</label><select id="cpa">${o(d1)}</select><label>Second person</label><select id="cpb">${o(d2)}</select><div id="er" class="er"></div><button class="btn" onclick="introduce()">Introduce them</button>`)}
