async function openShop(){if(!me)return openAuth("in");try{SHP=await api("GET","/shop")}catch(e){return toast(e.message)}drawShop()}
function drawShop(){const o=SHP.owned,bal=SHP.bal;modal(`${xb()}<h2 class="at">👗 Outfit shop</h2><p class="sub as">You have <b>${bal} XP</b> to spend.</p><div class="shg">${SHP.items.map(i=>{const own=o.includes(i.id),on=own&&(me.avatar||{})[i.slot]===i.val;return `<div class="shi">${AV({...avOf(me),[i.slot]:i.val},64)}<b>${esc(i.name)}</b>${own?`<button class="btn ${on?"o":""}" onclick="wear('${i.id}')">${on?"Take off":"Wear"}</button>`:`<button class="btn" ${bal<i.price?"disabled":""} onclick="buy('${i.id}')">⭐ ${i.price}</button>`}</div>`}).join("")}</div>`)}
async function buy(id){try{const r=await api("POST","/shop/buy",{id});me=r.user;SHP.owned=r.owned;SHP.bal=r.bal;toast("Bought! You are wearing it 🎉");drawShop();loadXP()}catch(e){toast(e.message)}}
async function wear(id){const it=SHP.items.find(x=>x.id===id),on=(me.avatar||{})[it.slot]===it.val;try{const r=await api("POST","/shop/wear",on?{slot:it.slot}:{id});me=r.user;drawShop()}catch(e){toast(e.message)}}
async function giftXP(id,n){try{await api("POST","/gift",{to:id,amount:n});toast("🎁 You sent "+n+" XP");loadXP()}catch(e){toast(e.message)}}
const streakCard=()=>{const x=XPV;if(!x||x.streak==null)return '<div id="stk"></div>';return `<div class="card stk" id="stk"><b>🔥 ${x.streak}-day streak</b><span>Best: ${x.best} days. Visit every day for bonus XP (+${Math.min(x.streak+1,7)*5} XP tomorrow).</span>${x.badges&&x.badges.length?`<div class="tags">${x.badges.map(b=>`<span>${esc(b)}</span>`).join("")}</div>`:'<p class="note" style="margin:6px 0 0">Badges show up as you play: streaks, favourite spots, matches.</p>'}</div>`};
const lbCard=()=>LB&&LB.top.length?`<div class="card"><b>🏆 This week’s top players</b>${LB.top.map((x,i)=>`<div class="row" onclick="bio(${x.user.id})" style="cursor:pointer;padding:6px 0"><b style="width:22px">${i+1}</b>${av(x.user,34)}<div style="flex:1"><b>${esc(x.user.name)}</b></div><span class="jb">⭐ ${x.xp}</span></div>`).join("")}${LB.me?`<p class="note">You are #${LB.me.rank} with ${LB.me.xp} XP this week.</p>`:""}</div>`:"";
async function loadLB(){if(!me)return;try{LB=await api("GET","/leaderboard");LB.top.forEach(x=>UC[x.user.id]=x.user);if(tab==="daily")render(1)}catch(e){}}
const agoN=t=>{const m=Math.floor((Date.now()-t)/6e4);return m<1?"just now":m<60?m+" min ago":m<1440?Math.floor(m/60)+" h ago":Math.floor(m/1440)+" d ago"};
const nBadge=()=>{const b=$("#nbd");if(b)b.textContent=NT.unread?(NT.unread>9?"9+":NT.unread):""};
async function loadNotifs(){if(!me)return;try{const r=await api("GET","/notifs"),mx=Math.max(0,...r.items.map(x=>x.id));if(NLAST>=0)r.items.filter(x=>x.id>NLAST&&!x.isread).forEach(x=>{toast(x.text);if(x.kind==="photos"){pollNow("mat");loadMatches()}try{if(document.hidden&&window.Notification&&Notification.permission==="granted")new Notification("Love in Lagos",{body:x.text})}catch(e){}});NLAST=mx;NT=r;nBadge()}catch(e){}}
async function openNotifs(){if(!me)return openAuth("in");await loadNotifs();const ics={match:"💘",msg:"💬",gift:"🎁",streak:"🔥",cupid:"💘",photos:"📸"},canP=window.Notification&&Notification.permission==="default";
modal(`${xb()}<h2 class="at">🔔 Notifications</h2>${canP?`<button class="btn o" onclick="askNotif()">Turn on phone alerts</button>`:""}${NT.items.length?NT.items.map(x=>`<div class="row" onclick="closeM();${x.kind==="cupid"&&UC[x.from_id]?`bio(${x.from_id})`:x.kind==="photos"&&UC[x.from_id]?`openChat(${x.from_id})`:`nav('${x.kind==="msg"||x.kind==="match"?"chat":"me"}')`}" style="cursor:pointer;opacity:${x.isread?.6:1}"><span style="font-size:24px">${ics[x.kind]||"🔔"}</span><div style="flex:1">${esc(x.text)}<div class="jb">${agoN(x.at)}</div></div></div>`).join(""):'<p class="note">Nothing yet. Matches, messages, gifts and streaks will show up here.</p>'}`);
if(NT.unread){try{await api("POST","/notifs/read");NT.unread=0;nBadge()}catch(e){}}}
function askNotif(){Notification.requestPermission().then(p=>{toast(p==="granted"?"Phone alerts are on (while the site is open) ✅":"Alerts stay off");closeM()})}
// ---------- my profile ----------
function prof(){if(!me)return gate("see your profile");const ints=me.interests||[],look=me.look||[];
return `<div class="pr"><div class="avw">${av(me,104)}<button class="edb" onclick="designer('edit')" aria-label="Edit bitmoji">${ic(IC.pen)}</button></div><h2>@${esc(me.username)}</h2><div class="jb">${esc(me.area||"Lagos")}</div></div><div class="card xpc"><b id="xpv">⭐ ${XPV?XPV.total:(me.xp||0)} XP</b><span id="xpt">total earned · 💰 ${XPV?XPV.bal:(me.bal||0)} to spend</span></div>${streakCard()}<div class="grid st"><div class="card"><b>${M.matches.length}</b><span>matches</span></div><div class="card"><b>${M.incoming.length}</b><span>requests</span></div></div><div class="card"><b>📸 Profile picture</b><p class="note" style="text-align:left">Only visible to a match after you've exchanged 100 messages.</p><div class="phr"><span class="phw${me.photo?" has":""}"><button type="button" class="php php-cam" onclick="camOpen('p')" aria-label="Open the camera to take a profile picture" title="Tap to take a picture">${me.photo?`<img src="${me.photo}" alt="">`:"📷"}</button></span><button class="btn o phb" onclick="$('#ppf').click()">${me.photo?"Change":"Upload"}</button>${me.photo?'<button class="btn o phb" onclick="delPh()">Remove</button>':""}<input id="ppf" type="file" accept="image/*" hidden onchange="uPh(this)"></div></div><button class="btn o" onclick="designer('edit')">🎨 Edit my bitmoji</button><div class="sech"><h3 class="sec">About you</h3><span id="svi" class="svi" role="status" aria-live="polite"></span></div><label>Username</label><input id="pu" maxlength="20" value="${esc(me.username)}" autocapitalize="none" oninput="psSet('username',this.value)" onblur="psFlush()"><label>About me <span class="op">(matches are based on this, your interests and what you look for)</span></label><textarea id="pb" rows="3" maxlength="160" placeholder="Tell people a little about you…" oninput="psSet('bio',this.value)" onblur="psFlush()">${esc(me.bio||"")}</textarea><label>Area in Lagos</label><select id="pa" onchange="psSet('area',this.value)"><option value="">Choose your area</option>${AREAS.map(a=>`<option ${me.area===a?"selected":""}>${a}</option>`).join("")}</select><label>Favourite spot</label><select id="pf" onchange="psSet('fav',this.value)"><option value="">Choose a spot</option>${SCN.map(s=>`<option ${me.fav===s[0]?"selected":""}>${s[0]}</option>`).join("")}</select><button class="btn o" onclick="openInts()">🎯 Interests · ${ints.length?ints.length+" picked":"choose up to 5"}</button><button class="btn o" style="margin-top:8px" onclick="openShop()">👗 Outfit shop</button><div id="pe" class="er"></div><button class="btn o" onclick="logout()">Log out</button>`}
function tgI(b,x){const a=me.interests=me.interests||[],i=a.indexOf(x);if(i>=0)a.splice(i,1);else if(a.length>=5)return toast("Up to 5 interests");else a.push(x);b.classList.toggle("on");api("PUT","/me",{interests:a}).catch(()=>{})}
function tgL(b,x){const a=me.look=me.look||[],i=a.indexOf(x);if(i>=0)a.splice(i,1);else a.push(x);b.classList.toggle("on");api("PUT","/me",{look:a}).catch(()=>{})}
// ---------- profile autosave (replaces the old Save profile button) ----------
// Edits are collected, saved after a short pause, and never overwritten by an older request: only one save runs at a time,
// and anything typed while a save is running is sent in the next one.
const PS={pend:{},timer:0,busy:0,again:0,fail:0,ft:0,st:"",err:null};
function psUI(s,m,retry){PS.st=s;const e=$("#svi");if(!e)return;clearTimeout(PS.ft);e.className="svi "+s;e.innerHTML=s==="saving"?'<span class="spn"></span>Saving…':s==="saved"?"✓ Saved":s==="err"?"⚠️ "+esc(m||"Couldn’t save")+(retry?' · <a class="lnk2" onclick="psFlush()">Retry</a>':""):"";if(s==="saved")PS.ft=setTimeout(()=>{if(PS.st==="saved")psUI("")},2000)}
const psErr=t=>{const e=$("#pe");if(e)e.textContent=t||""};
function psSet(k,v){if(!me)return;v=String(v);
if(k==="username"){v=v.trim().toLowerCase();if(v===me.username){delete PS.pend.username;return psErr("")}if(!/^[a-z0-9_.]{3,20}$/.test(v)){delete PS.pend.username;return psErr("Username: 3-20 letters, numbers, _ or .")}}
else me[k]=v;
psErr("");PS.pend[k]=k==="bio"?v.trim():v;PS.fail=0;clearTimeout(PS.timer);PS.timer=setTimeout(psFlush,k==="bio"||k==="username"?900:200)}
async function psFlush(ka){clearTimeout(PS.timer);if(PS.busy){PS.again=1;return}const keys=Object.keys(PS.pend);if(!keys.length)return;
PS.busy=1;psUI("saving");let bad=0,final=0;
for(const g of [keys.filter(k=>k!=="username"),keys.filter(k=>k==="username")].filter(x=>x.length)){ // username is sent alone so one rejected field cannot block the others
const body={};g.forEach(k=>{body[k]=PS.pend[k];delete PS.pend[k]});
try{const r=await api("PUT","/me",body,ka);g.forEach(k=>{if(k in PS.pend)return;if(k==="username"){me.username=r.username||body.username;me.name=r.name||me.username}else me[k]=body[k]})}
catch(e){bad=1;PS.err=e;if(e.status&&e.status<500&&e.status!==429){final=1;psErr(e.message)}else g.forEach(k=>{if(!(k in PS.pend))PS.pend[k]=body[k]})}}
PS.busy=0;
const h=document.querySelector(".pr h2"),j=document.querySelector(".pr .jb"),pf=document.querySelector("header .pf");if(h&&!bad)h.textContent="@"+me.username;if(j)j.textContent=me.area||"Lagos";if(pf&&!bad)pf.innerHTML=av(me,26)+esc(me.name);
if(!bad)psUI("saved");else if(final)psUI("err","Not saved");else{psUI("err","Couldn’t save",1);if(PS.fail++<3)PS.timer=setTimeout(psFlush,5000)}
if(PS.again||(!bad&&Object.keys(PS.pend).length)){PS.again=0;psFlush(ka)}}
async function psWait(){clearTimeout(PS.timer);await psFlush();for(let i=0;i<30&&PS.busy;i++)await new Promise(r=>setTimeout(r,100))}
addEventListener("pagehide",()=>psFlush(1));document.addEventListener("visibilitychange",()=>{if(document.hidden)psFlush(1)});
function readPh(f,cb){if(!f)return;if(!/^image\//.test(f.type))return toast("Please choose an image");const r=new FileReader();r.onload=()=>{const i=new Image();i.onload=()=>{const k=Math.min(1,256/Math.max(i.width,i.height)),c=document.createElement("canvas");c.width=Math.round(i.width*k);c.height=Math.round(i.height*k);c.getContext("2d").drawImage(i,0,0,c.width,c.height);cb(c.toDataURL("image/jpeg",.8))};i.src=r.result};r.readAsDataURL(f)}
function sPh(el){readPh(el.files[0],d=>{phd=d;$("#php").innerHTML=`<img src="${d}">`})}
function uPh(el){readPh(el.files[0],async d=>{try{me=await api("PUT","/me",{photo:d});render(1);toast("Photo saved ✅")}catch(e){toast(e.message)}})}
async function delPh(){try{me=await api("PUT","/me",{photo:""});render(1)}catch(e){toast(e.message)}}
async function logout(silent){if(!silent)await psWait();if(!silent){try{await api("POST","/presence",{loc:-1})}catch(e){}}setTok("");me=null;M={incoming:[],matches:[],sent:[]};PEO=[];PREV=null;MINIT=0;LOW={};DECL={};POPPED={};PH={};tab="home";cur=null;render();if(!silent)toast("Logged out")}
// ---------- start ----------
// ---------- polling scheduler: far fewer requests, same feel ----------
// Each job has its own pace. Everything slows down when the person is idle, almost stops when the tab is hidden,
// and refreshes at once when they open a tab or come back. A chat is checked every 3 s for a minute after anything
// happens in it (and after you send something), otherwise every 7 s.
const POLL={last:{},act:Date.now(),hot:0};
const due=(k,ms)=>{const n=Date.now();if(n-(POLL.last[k]||0)>=ms){POLL.last[k]=n;return true}return false};
const pollNow=(...k)=>k.forEach(x=>POLL.last[x]=0);
["pointerdown","keydown","touchstart","scroll"].forEach(e=>addEventListener(e,()=>{POLL.act=Date.now()},{passive:true,capture:true}));
document.addEventListener("visibilitychange",()=>{if(!document.hidden){POLL.act=Date.now();POLL.last={};tick()}});
function tick(){if(!me)return;T++;
if(document.hidden){if(due("not",60000))loadNotifs();return} // a hidden tab only checks for new notifications, once a minute
const idle=Date.now()-POLL.act,k=idle>12e4?4:idle>45e3?2:1; // 4x slower after 2 minutes without touching the screen, 2x after 45 seconds
if(due("pres",60000*k))presence();
if(tab==="home"&&due("ppl",15000*k))loadPeople();
if(due("mat",(tab==="chat"?10000:25000)*k))loadMatches();
if(due("xp",60000*k))loadXP();
if(due("not",20000*k))loadNotifs();
if(tab==="chat"&&cur&&due("thr",(POLL.hot>Date.now()?3000:7000)*(idle>3e5?2:1)))loadThread(1); // an open chat stays responsive while you read, and only slows after 5 minutes of no touching
if(tab==="corner"&&due("vis",20000*k))loadVisitors()}
const VK="lil_view";function saveView(){try{localStorage.setItem(VK,JSON.stringify({tab,sc,cur,BACK}))}catch(e){}} // remembers the page, so a refresh brings you back to it
function offlineV(){$("#app").innerHTML='<div class="splash"><i>💘</i><b>Love in Lagos</b><span>We can’t reach the server right now. Check your connection.</span><button class="btn" onclick="location.reload()">Try again</button></div>'}
async function boot(){let mtP=null;if(TOK){const meP=api("GET","/me");mtP=loadMatches();mtP.catch(()=>{});try{me=await meP}catch(e){if(e&&e.status===401)setTok("");else return offlineV()}}
try{const v=JSON.parse(localStorage.getItem(VK)||"null");if(v){tab=v.tab||"home";sc=+v.sc||0;BACK=v.BACK||"";cur=v.cur||null}}catch(e){}
if(!SCN[sc])sc=0;if(me){if(cur){try{await mtP}catch(e){}if(!M.matches.some(x=>x.user.id===cur))cur=null}}else cur=null;
render();if(me){presence();loadXP();loadNotifs();loadPeople();if(tab==="daily")loadDaily();if(tab==="corner")loadVisitors();if(tab==="chat"&&cur)loadThread()}["pres","ppl","mat","xp","not","thr","vis"].forEach(k=>POLL.last[k]=Date.now());setInterval(tick,3000)}
boot();
